-- -----------------------------------------------------------------------------------------------------------------------
-- ubicacion


-- este sirve
INSERT INTO  proyectoSchemaDefinitivo.ubicacion(
                    idUbicacion,
                    ciudad,
                    conglomerado,
                    IndicadorPobreza_area,
                    Provincia_idProvincia
                    )

SELECT ROW_NUMBER() OVER (ORDER BY v.ciudad) AS id,
       v.ciudad, v.conglomerado, v.area, n.provincia
FROM vivienda.enemdu_vivienda_final v
JOIN vivienda.nueva_tabla n ON v.id = n.id
JOIN proyectoSchemaDefinitivo.provincia p ON p.idProvincia = n.provincia;

-- -----------------------------------------------------------------------------------------------------------------------
-- servicio higienico
-- este sirve
INSERT INTO  proyectoSchemaDefinitivo.serviciohigienico(
                    idServicioHigienico,
                    tipoServicioHigienico,
                    instalacionSanitariaCercanaOPrestrada,
                    noServicioHigienicoEntonces
                    )

SELECT ROW_NUMBER() OVER (ORDER BY v.tipoServicioHigienico) AS id,
       v.tipoServicioHigienico, v.instalacionSanitariaCercanaOPrestada, v.noServicioHigienicoEntonces
FROM vivienda.enemdu_vivienda_final v;
-- -----------------------------------------------------------------------------------------------------



INSERT INTO proyectoSchemaDefinitivo.Vivienda (
  idVivienda,
  accesoVivienda,
  tipoVivienda,
  pisoMaterial,
  pisoEstado,
  paredMaterial,
  paredEstado,
  cubiertaTecho,
  cubiertaEstado,
  eliminaBasura,
  Ubicacion_idUbicacion,
  ServicioHigienico_idServicioHigienico
)
select v.id_vivienda, v.accesoVivienda, v.tipoVivienda, v.pisoMaterial,
       v.pisoEstado, v.paredMaterial, v.paredEstado, v.cuviertaTecho,
       v.cuviertaEstado, v.eliminaBasura, u.idUbicacion, s.idServicioHigienico
from vivienda.enemdu_vivienda_final v
JOIN proyectoschemadefinitivo.ubicacion u ON v.id = u.idUbicacion
JOIN proyectoSchemaDefinitivo.ServicioHigienico s ON u.idUbicacion = s.idServicioHigienico;





-- --------------------
INSERT INTO `proyectoSchemaDefinitivo`.`ServicioPotable`(
  dondeObtieneAgua,
  tieneMedidorAgua,
  esJuntaAgua,
  aguaRecibelaVivienda,
  servicioDucha,
  Vivienda_idVivienda
)
SELECT distinct v.dondeObtieneAgua, v.tieneMedidorAgua, v.esJuntaAgua, v.aguaRecibelaVivienda, v.servicioDucha, v2.idVivienda
FROM vivienda.enemdu_vivienda_final v
INNER JOIN proyectoSchemaDefinitivo.vivienda v2
ON v.id_vivienda = v2.idVivienda;

