-- hogar

INSERT INTO `proyectoSchemaDefinitivo`.`Hogar` (
                                            idHogar,
                                            numCuartos,
                                            numDormitorios,
                                            cuartoNegocio,
                                            tipoAlumbrado,
                                            tieneHogarMotos,
                                            numMotos,
                                            tieneHogarVehiculos,
                                            numVehiculos,
                                            materialesCocinan,
                                            cuartoCocina,
                                            Vivienda_idVivienda
)
SELECT
    e.id_hogar,
    e.numCuartos,
    e.numDormitorios,
    e.cuartoNegocio,
    e.tipoAlumbrado,
    e.tieneHogarMotos,
    e.numMotos,
    e.tieneHogarVehiculos,
    e.numVehiculos,
    e.materialesCocinan,
    e.cuartoCocina,
    e.id_vivienda
FROM vivienda.enemdu_vivienda_final e;

-- ------------------------------------------



INSERT INTO `proyectoSchemaDefinitivo`.`Combustible`(
	idCombustibles,
	abastecimientoSuper,
    gastoSuper,
    abastecimientoExtra,
    gastoExtra,
    abastecimientoDiesel,
    gastoDisel,
    abastecimientoEco_Pais,
    gastoEco_Pais,
    abastecimientoEletricidad,
    gastoElectricidad,
    abastecimientoGas,
    gastoGas,
    Hogar_idHogar
)
SELECT ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) AS id,
       e.abastesimientoSuper, e.gastoCombSuper, e.abastesimientoEXTRA,
       e.gastoCombEXTRA, e.abastesimientoDiesel, e.gastoCombDiesel,
       e.abastecimientoEco, e.gastoCombEco, e.abastecimientoElectricidad,
       e.gastoElectricidad, e.abastecimientoGas, e.gastoGas, e.id_hogar
FROM vivienda.enemdu_vivienda_final e;

-- ------------------------------------------


INSERT INTO  proyectoSchemaDefinitivo.arriendo(
                    idarriendo,
                    valorArriendo,
                    incluyePagoAgua,
                    incluyePagoLuz,
                    parentezcoPropietarioVivienda,
                    Hogar_idHogar
                    )

SELECT ROW_NUMBER() OVER (ORDER BY v.valorArriendo) AS id,
       v.valorArriendo, v.incluyePagoAgua, v.incluyePagoLuz, v.parentezcoPropietariovivienda,v.id_hogar
FROM vivienda.enemdu_vivienda_final v;











